//! Shared exclusive-Text normalization over genuine native and inert trees.
use super::*;
use crate::javascript::{NativeNormalizeInfo,NativeNormalizeEvent,NativeChildListChange};
struct View{parent:u32,children:Vec<u32>,flags:Vec<u8>,removed:usize}
enum Parent{Main(usize,Vec<usize>),Inert(u32,Vec<u32>)}
enum Update{Main(usize,DomString),Direct(u32,DomString),Parsed(u32,GeneratedNode,Option<usize>)}
enum RangeChange{Remove{parent:u32,node:u32,index:usize},Merge{parent:u32,node:u32,keeper:u32,index:usize,offset:usize}}
pub(in crate::scripting) struct Plan{target:u32,parents:Vec<Parent>,updates:Vec<Update>,removed:Vec<u32>,ranges:Vec<RangeChange>,payload:usize,released:usize,generated:usize,nodes:usize,entries:usize,sources:usize,generation:Option<u64>,events:usize,connected:bool}
impl Bridge<'_>{
 pub(in crate::scripting) fn normalize_receiver(&self,object:u32)->bool{!self.is_frame_handle(object)&&self.namespace_receiver(object)}
 fn normalize_text(&self,object:u32)->bool{if let Some(kind)=self.inert_node_type(object){return kind==3;}node_index(object).is_some_and(|node|self.dom_accessible(node)&&matches!(self.doc.nodes[node].kind,NodeKind::Text(_)))}
 fn normalize_children(&mut self,object:u32)->Result<Vec<u32>,String>{
  if self.attr_receiver(object)||self.character_data_receiver(object)||self.doctype_receiver(object){return Ok(Vec::new());}
  if self.template_receiver(object)&&self.inert_node_type(object).is_none()&&self.template_source(object).is_some_and(|(_,initial)|initial.is_some()){return Ok(Vec::new());}
  let count=self.whole_text_child_count(object)?;self.state.work(count.checked_mul(self.state.inert_documents.adopted.lookup_work()+2).ok_or("Normalization traversal work overflow.")?)?;self.state.copies(count.checked_mul(size_of::<u32>()).ok_or("Normalization traversal storage overflow.")?)?;
  let mut children=Vec::new();children.try_reserve_exact(count).map_err(|_|"Cannot reserve normalization children.")?;for index in 0..count{children.push(self.whole_text_child(object,index).ok_or("Normalization child disappeared.")?);}Ok(children)
 }
 fn normalize_parent_guard(&mut self,parent:u32)->Result<(),String>{
  if self.state.inert_documents.node(parent).is_some(){return Ok(());}let node=if parent==DOCUMENT{0}else{self.dom_node(parent)?};if node!=0&&self.doc.nodes[node].namespace!=crate::html::Namespace::Html&&!matches!(self.doc.nodes[node].kind,NodeKind::DocumentFragment){return Err("Normalization requires known attribute/tree namespace provenance.".into());}self.mutation_ancestors(node)?;if self.dom_script(node){return Err("Normalization of native script contents requires its children-changed lifecycle hook.".into());}Ok(())
 }
 pub(in crate::scripting) fn prepare_shared_normalize(&mut self,target:u32)->Result<NativeNormalizeInfo,String>{
  if !self.normalize_receiver(target){return Err("normalize requires a genuine accessible Node.".into());}if self.state.normalize_plan.is_some(){return Err("A normalization proposal is already active.".into());}self.state.rebuild(self.doc)?;
  let mut stack=self.normalize_children(target)?;stack.reverse();let mut order=Vec::new();let maximum=self.doc.nodes.len().checked_add(self.inert_node_count()).and_then(|n|n.checked_add(1)).ok_or("Normalization traversal bound overflow.")?;let mut visited=0usize;
  while let Some(node)=stack.pop(){visited=visited.checked_add(1).filter(|&n|n<=maximum).ok_or("Invalid or cyclic normalization tree.")?;self.state.work(1)?;if self.normalize_text(node){self.state.copies(size_of::<u32>())?;order.try_reserve(1).map_err(|_|"Cannot reserve normalization Text order.")?;order.push(node);}else{let children=self.normalize_children(node)?;self.state.copies(children.len().checked_mul(size_of::<u32>()).ok_or("Normalization stack copy overflow.")?)?;stack.try_reserve(children.len()).map_err(|_|"Cannot reserve normalization stack.")?;stack.extend(children.into_iter().rev());}}
  let mut parent_ids=Vec::new();self.state.copies(order.len().checked_mul(size_of::<u32>()).ok_or("Normalization parent metadata overflow.")?)?;parent_ids.try_reserve_exact(order.len()).map_err(|_|"Cannot reserve normalization parents.")?;for &node in &order{parent_ids.push(self.whole_text_parent(node)?.ok_or("Normalization descendant lost its parent." )?);}let sorting=(usize::BITS-order.len().leading_zeros())as usize+1;self.state.work(order.len().checked_mul(sorting).ok_or("Normalization sorting work overflow.")?)?;parent_ids.sort_unstable();parent_ids.dedup();
  let mut views=Vec::new();let mut positions=Vec::new();self.state.copies(parent_ids.len().checked_mul(size_of::<View>()).ok_or("Normalization view storage overflow.")?)?;views.try_reserve_exact(parent_ids.len()).map_err(|_|"Cannot reserve normalization views.")?;
  for parent in parent_ids{let children=self.normalize_children(parent)?;self.state.copies(children.len().checked_mul(size_of::<(u32,usize,usize)>()+size_of::<u8>()).ok_or("Normalization index metadata overflow.")?)?;positions.try_reserve(children.len()).map_err(|_|"Cannot reserve normalization positions.")?;let view=views.len();for(index,&node)in children.iter().enumerate(){positions.push((node,view,index));}let mut flags=Vec::new();flags.try_reserve_exact(children.len()).map_err(|_|"Cannot reserve normalization flags.")?;flags.resize(children.len(),0);views.push(View{parent,children,flags,removed:0});}
  self.state.work(positions.len().checked_mul((usize::BITS-positions.len().leading_zeros())as usize+1).ok_or("Normalization position work overflow.")?)?;positions.sort_unstable_by_key(|entry|entry.0);if positions.windows(2).any(|pair|pair[0].0==pair[1].0){return Err("Duplicate normalization tree identity.".into());}
  let mut updates=Vec::new();let mut removed=Vec::new();let mut ranges=Vec::new();let mut events=Vec::new();let mut payload=0usize;let mut released=0usize;let mut generated=0usize;let mut connected=false;
  for node in order{self.state.work(sorting+1)?;let at=positions.binary_search_by_key(&node,|entry|entry.0).map_err(|_|"Missing normalization Text position.")?;let(_,view,index)=positions[at];if views[view].flags[index]!=0{continue;}let parent=views[view].parent;self.normalize_parent_guard(parent)?;
   let mut end=index;while end<views[view].children.len()&&self.normalize_text(views[view].children[end]){end+=1;}
   let mut keeper=None;let mut offset=0usize;
   for slot in index..end{let child=views[view].children[slot];let data=self.character_data_source(child).ok_or("Missing normalization Text data.")?;let length=data.utf16_len();self.state.work(data.used_bytes().checked_add(1).ok_or("Normalization Text work overflow.")?)?;
    if keeper.is_none()&&length!=0{
     keeper=Some(child);offset=length;views[view].flags[slot]=1;
     self.state.copies(size_of::<NativeNormalizeEvent>())?;events.try_reserve(1).map_err(|_|"Cannot reserve normalization data event.")?;events.push(NativeNormalizeEvent::Data(child));
     let mut parts=Vec::new();self.state.copies((end-slot).checked_mul(size_of::<&DomString>()).ok_or("Normalization Text references overflow.")?)?;parts.try_reserve_exact(end-slot).map_err(|_|"Cannot reserve normalization Text references.")?;let mut extra=0usize;for &following in &views[view].children[slot..end]{let data=self.character_data_source(following).ok_or("Missing normalization source.")?;parts.push(data);if following!=child{extra=extra.checked_add(data.utf16_len()).ok_or("Normalization joined length overflow.")?;}}
     if extra!=0{let(logical,copy)=(DomString::concat_size(&parts)?.0,DomString::concat_copy_work(&parts)?);if logical>self.state.limits.host.string_bytes{return Err("Normalized Text exceeds the host string bound.".into());}drop(parts);self.state.copies(copy.checked_add((end-slot).checked_mul(size_of::<&DomString>()).ok_or("Normalization references overflow.")?).ok_or("Normalization copy work overflow.")?)?;let mut parts=Vec::new();parts.try_reserve_exact(end-slot).map_err(|_|"Cannot reserve normalization result references.")?;for &following in &views[view].children[slot..end]{parts.push(self.character_data_source(following).unwrap());}let text=DomString::concat(&parts,DomString::storage_bound(self.state.limits.host.string_bytes)?)?;drop(parts);
      self.state.copies(size_of::<Update>())?;updates.try_reserve(1).map_err(|_|"Cannot reserve normalization update.")?;
      if let Some(old)=self.state.inert_documents.node(child){match old.kind{Kind::Text(ref data)=>{released=released.checked_add(data.capacity()).ok_or("Normalization refund overflow.")?;payload=payload.checked_add(text.capacity()).ok_or("Normalization payload overflow.")?;updates.push(Update::Direct(child,text));},Kind::Parsed{source,initial_template}=>{let(raw,unsafe_nonce)=self.parsed_source(source).ok_or("Missing normalization snapshot.")?;let node=Node{kind:NodeKind::Text(text),namespace:raw.namespace,children:Vec::new()};payload=payload.checked_add(node_bytes(&node)).and_then(|n|n.checked_add(size_of::<Node>()+2*size_of::<usize>())).ok_or("Normalization snapshot overflow.")?;updates.push(Update::Parsed(child,GeneratedNode{node:Rc::new(node),unsafe_nonce},initial_template));generated+=1;},_=>return Err("Normalization keeper is not Text.".into())}}
      else{let index=node_index(child).ok_or("Missing native normalization keeper.")?;released=released.checked_add(self.doc.nodes[index].kind.character_data_capacity().unwrap()).ok_or("Normalization native refund overflow.")?;payload=payload.checked_add(text.capacity()).ok_or("Normalization native payload overflow.")?;updates.push(Update::Main(index,text));}
     }
    }else{
     let dynamic=slot-views[view].removed;self.state.copies(size_of::<RangeChange>()+size_of::<u32>()+size_of::<NativeNormalizeEvent>()+size_of::<u32>())?;ranges.try_reserve(1).map_err(|_|"Cannot reserve normalization Range change.")?;removed.try_reserve(1).map_err(|_|"Cannot reserve normalized removals.")?;events.try_reserve(1).map_err(|_|"Cannot reserve normalization removal event.")?;let mut nodes=Vec::new();nodes.try_reserve_exact(1).map_err(|_|"Cannot reserve normalization removed node.")?;nodes.push(child);
     let previous=if let Some(keeper)=keeper{Some(keeper)}else{index.checked_sub(1).map(|before|views[view].children[before])};let next=views[view].children.get(slot+1).copied();events.push(NativeNormalizeEvent::Child(NativeChildListChange{target:parent,added:Vec::new(),removed:nodes,previous,next}));
     if let Some(keeper)=keeper{ranges.push(RangeChange::Merge{parent,node:child,keeper,index:dynamic,offset});offset=offset.checked_add(length).ok_or("Normalization Range offset overflow.")?;}else{ranges.push(RangeChange::Remove{parent,node:child,index:dynamic});}views[view].flags[slot]=2;views[view].removed+=1;removed.push(child);
    }
   }
  }
  let mut parents=Vec::new();self.state.copies(views.len().checked_mul(size_of::<Parent>()).ok_or("Normalization parent plan overflow.")?)?;parents.try_reserve_exact(views.len()).map_err(|_|"Cannot reserve normalized parent plan.")?;
  for view in views{if view.removed==0{continue;}let count=view.children.len()-view.removed;if self.state.inert_documents.node(view.parent).is_some(){let old=&self.state.inert_documents.node(view.parent).unwrap().children;released=released.checked_add(old.capacity()*size_of::<u32>()).ok_or("Normalization child refund overflow.")?;self.state.copies(count.checked_mul(size_of::<u32>()).ok_or("Normalization child copy overflow.")?)?;let mut children=Vec::new();children.try_reserve_exact(count).map_err(|_|"Cannot reserve normalized inert links.")?;for(node,flag)in view.children.into_iter().zip(view.flags){if flag!=2{children.push(node);}}payload=payload.checked_add(children.capacity()*size_of::<u32>()).ok_or("Normalization inert link storage overflow.")?;parents.push(Parent::Inert(view.parent,children));}
   else{let index=if view.parent==DOCUMENT{0}else{node_index(view.parent).ok_or("Missing normalization parent.")?};released=released.checked_add(child_link_bytes(&self.doc.nodes[index].children)).ok_or("Normalization native link refund overflow.")?;self.state.copies(count.checked_mul(size_of::<usize>()).ok_or("Normalization native link copy overflow.")?)?;let mut children=Vec::new();children.try_reserve_exact(count).map_err(|_|"Cannot reserve normalized native links.")?;for(node,flag)in view.children.into_iter().zip(view.flags){if flag!=2{children.push(node_index(node).ok_or("Invalid native normalized child.")?);}}payload=payload.checked_add(child_link_bytes(&children)).ok_or("Normalization native link payload overflow.")?;connected|=self.state.dom.connected[index];parents.push(Parent::Main(index,children));}
  }
  self.state.prepare_range_changes(ranges.len(),1)?;let count=events.len();self.state.normalize_plan=Some(Plan{target,parents,updates,removed,ranges,payload,released,generated,nodes:self.doc.nodes.len(),entries:self.state.inert_documents.entries.len(),sources:self.state.inert_documents.generated.len(),generation:self.state.dom_commits,events:count,connected});Ok(NativeNormalizeInfo{events})
 }
 pub(in crate::scripting) fn abort_shared_normalize(&mut self,target:u32){if self.state.normalize_plan.as_ref().is_some_and(|plan|plan.target==target){self.state.normalize_plan=None;}}
 pub(in crate::scripting) fn commit_shared_normalize(&mut self,target:u32)->Result<(),String>{
  let plan=self.state.normalize_plan.take().ok_or("Missing normalization proposal.")?;if plan.target!=target||plan.nodes!=self.doc.nodes.len()||plan.entries!=self.state.inert_documents.entries.len()||plan.sources!=self.state.inert_documents.generated.len()||plan.generation!=self.state.dom_commits{return Err("Normalization proposal changed before publication.".into());}if plan.events==0{return Ok(());}self.reserve_inert_storage(0,plan.payload,plan.generated,plan.released,0)?;
  for change in plan.ranges{match change{RangeChange::Remove{parent,node,index}=>self.state.ranges_normalize_remove(parent,node,index),RangeChange::Merge{parent,node,keeper,index,offset}=>self.state.ranges_normalize_merge(parent,node,keeper,index,offset)}}
  for update in plan.updates{match update{Update::Main(node,data)=>self.doc.nodes[node].kind=NodeKind::Text(data),Update::Direct(node,text)=>{let Kind::Text(data)=&mut self.state.inert_documents.node_mut(node).unwrap().kind else{unreachable!()};*data=text;},Update::Parsed(node,source,initial_template)=>{let index=self.state.inert_documents.generated.len();self.state.inert_documents.generated.push(source);self.state.inert_documents.node_mut(node).unwrap().kind=Kind::Parsed{source:ParsedSource::Generated(index),initial_template};}}}
  for parent in plan.parents{match parent{Parent::Main(node,children)=>self.doc.nodes[node].children=children,Parent::Inert(node,children)=>{self.state.inert_documents.node_mut(node).unwrap().children=children;self.sync_document_children(node);}}}
  for node in plan.removed{if let Some(item)=self.state.inert_documents.node_mut(node){item.parent=None;}else{let node=node_index(node).expect("admitted normalization node");self.state.tree.parents[node]=None;self.state.dom.connected[node]=false;self.state.detached_nodes.insert(node);}}
  for _ in 0..plan.events{self.state.dom_committed();}self.state.dirty=true;if plan.connected{self.state.layout_changed();}Ok(())
 }
}
